int led = 13;

void setup() {
    pinMode(led, OUTPUT);  // Configura el pin 13 como salida de voltaje
}

void loop() {
    digitalWrite(led, HIGH); // Envía 5V para encender el LED
    delay(1000);            // Espera 1 segundo (1000 ms)

    digitalWrite(led, LOW);  // Envía 0V para apagar el LED
    delay(1000);            // Espera 1 segundo (1000 ms)
}
